(()=>{try{document.addEventListener('keydown',e=>{if(e.key==='F12')return e.preventDefault();if(e.ctrlKey&&e.shiftKey&&['I','i','J','j','C','c'].includes(e.key))return e.preventDefault();if(e.ctrlKey&&['U','u'].includes(e.key))return e.preventDefault()}),sessionStorage.getItem('rc_disabled_seen')||(()=>{const e=document.createElement('div');e.textContent='Right-click and inspect are discouraged on this site.',e.style.position='fixed',e.style.bottom='12px',e.style.right='12px',e.style.background='rgba(0,0,0,0.7)',e.style.color='white',e.style.padding='8px 10px',e.style.borderRadius='6px',e.style.zIndex=1000,e.style.pointerEvents='none',document.body.appendChild(e),setTimeout(()=>e.remove(),4e3),sessionStorage.setItem('rc_disabled_seen','1')})()}catch(e){}})();
